06.IO操作01.打开和关闭文件 os.Open()函数能够打开一个文件，返回一个*File和一个err。 对得到的文件实例调用close()方法能够关闭文件。 为了防止文件忘记关闭，我们通常使用defer注册文件关闭语句。 12345678910111213141516package mainimport ( &quot;fmt&quot; &quot;os&quot;)func main() &#123; // 只读方式打开当前目录下的main.go文件 file, err := os.Open(&quot;./main.go&quot;) if err != nil &#123; fmt.Println(&quot;open file failed!, err:&quot;, err) return &#125; // 关闭文件 file.Close()&#125; 02.读取文件2.1 file.Read()指定读取size1234567891011121314151617181920212223242526272829package mainimport ( &quot;fmt&quot; &quot;io&quot; &quot;os&quot;)func main() &#123; // 只读方式打开当前目录下的main.go文件 file, err := os.Open(&quot;./main.go&quot;) if err != nil &#123; fmt.Println(&quot;open file failed!, err:&quot;, err) return &#125; defer file.Close() // 使用Read方法读取数据，每次只读取128个字节 var tmp = make([]byte, 128) n, err := file.Read(tmp) if err == io.EOF &#123; fmt.Println(&quot;文件读完了&quot;) return &#125; if err != nil &#123; fmt.Println(&quot;read file failed, err:&quot;, err) return &#125; fmt.Printf(&quot;读取了%d字节数据
&quot;, n) fmt.Println(string(tmp[:n]))&#125; 2.2 循环读取 使用for循环读取文件中的所有数据。 1234567891011121314151617181920212223242526272829303132package mainimport ( &quot;fmt&quot; &quot;io&quot; &quot;os&quot;)func main() &#123; // 只读方式打开当前目录下的main.go文件 file, err := os.Open(&quot;./main.go&quot;) if err != nil &#123; fmt.Println(&quot;open file failed!, err:&quot;, err) return &#125; defer file.Close() // 循环读取文件 var content []byte var tmp = make([]byte, 128) for &#123; n, err := file.Read(tmp) if err == io.EOF &#123; fmt.Println(&quot;文件读完了&quot;) break &#125; if err != nil &#123; fmt.Println(&quot;read file failed, err:&quot;, err) return &#125; content = append(content, tmp[:n]...) &#125; fmt.Println(string(content))&#125; 2.3 bufio按行读取 bufio是在file的基础上封装了一层API，支持更多的功能。 12345678910111213141516171819202122232425262728293031323334package mainimport ( &quot;bufio&quot; &quot;fmt&quot; &quot;io&quot; &quot;os&quot;)// bufio按行读取示例func main() &#123; file, err := os.Open(&quot;./main.go&quot;) if err != nil &#123; fmt.Println(&quot;open file failed, err:&quot;, err) return &#125; defer file.Close() reader := bufio.NewReader(file) for &#123; line, err := reader.ReadString(&#x27;
&#x27;) //注意是字符 if err == io.EOF &#123; if len(line) != 0 &#123; fmt.Println(line) &#125; fmt.Println(&quot;文件读完了&quot;) break &#125; if err != nil &#123; fmt.Println(&quot;read file failed, err:&quot;, err) return &#125; fmt.Print(line) &#125;&#125; 2.4 ioutil读取整个文件 io/ioutil包的ReadFile方法能够读取完整的文件，只需要将文件名作为参数传入。 12345678910111213141516package mainimport ( &quot;fmt&quot; &quot;io/ioutil&quot;)// ioutil.ReadFile读取整个文件func main() &#123; content, err := ioutil.ReadFile(&quot;./main.go&quot;) if err != nil &#123; fmt.Println(&quot;read file failed, err:&quot;, err) return &#125; fmt.Println(string(content))&#125; 03.写入文件3.0 参数说明 os.OpenFile()函数能够以指定模式打开文件，从而实现文件写入相关功能。 123func OpenFile(name string, flag int, perm FileMode) (*File, error) &#123; ...&#125; 其中： name：要打开的文件名 flag：打开文件的模式，模式有以下几种 模式 含义 os.O_WRONLY 只写 os.O_CREATE 创建文件 os.O_RDONLY 只读 os.O_RDWR 读写 os.O_TRUNC 清空 os.O_APPEND 追加 perm 1234567891011121314151617181920212223242526 ：文件权限，一个八进制数 - r（读）04，w（写）02，x（执行）01。### 3.1 Write和WriteString```gopackage mainimport ( &quot;fmt&quot; &quot;os&quot;)func main() &#123; file, err := os.OpenFile(&quot;xx.txt&quot;, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0666) if err != nil &#123; fmt.Println(&quot;open file failed, err:&quot;, err) return &#125; defer file.Close() str := &quot;hello 沙河&quot; file.Write([]byte(str)) //写入字节切片数据 file.WriteString(&quot;hello 小王子&quot;) //直接写入字符串数据&#125; 3.2 bufio.NewWriter123456789101112131415161718192021package mainimport ( &quot;bufio&quot; &quot;fmt&quot; &quot;os&quot;)func main() &#123; file, err := os.OpenFile(&quot;xx.txt&quot;, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0666) if err != nil &#123; fmt.Println(&quot;open file failed, err:&quot;, err) return &#125; defer file.Close() writer := bufio.NewWriter(file) for i := 0; i &lt; 10; i++ &#123; writer.WriteString(&quot;hello沙河
&quot;) //将数据先写入缓存 &#125; writer.Flush() //将缓存中的内容写入文件&#125; 3.3 ioutil.WriteFile123456789101112131415package mainimport ( &quot;fmt&quot; &quot;io/ioutil&quot;)func main() &#123; str := &quot;hello 沙河&quot; err := ioutil.WriteFile(&quot;./xx.txt&quot;, []byte(str), 0666) if err != nil &#123; fmt.Println(&quot;write file failed, err:&quot;, err) return &#125;&#125; 04.练习4.1 copyFile 借助io.Copy()实现一个拷贝文件函数。 1234567891011121314151617181920212223242526// CopyFile 拷贝文件函数func CopyFile(dstName, srcName string) (written int64, err error) &#123; // 以读方式打开源文件 src, err := os.Open(srcName) if err != nil &#123; fmt.Printf(&quot;open %s failed, err:%v.
&quot;, srcName, err) return &#125; defer src.Close() // 以写|创建的方式打开目标文件 dst, err := os.OpenFile(dstName, os.O_WRONLY|os.O_CREATE, 0644) if err != nil &#123; fmt.Printf(&quot;open %s failed, err:%v.
&quot;, dstName, err) return &#125; defer dst.Close() return io.Copy(dst, src) //调用io.Copy()拷贝内容&#125;func main() &#123; _, err := CopyFile(&quot;dst.txt&quot;, &quot;src.txt&quot;) if err != nil &#123; fmt.Println(&quot;copy file failed, err:&quot;, err) return &#125; fmt.Println(&quot;copy done!&quot;)&#125; 4.2 实现一个cat命令 使用文件操作相关知识，模拟实现linux平台cat命令的功能。 123456789101112131415161718192021222324252627282930313233343536373839package mainimport ( &quot;bufio&quot; &quot;flag&quot; &quot;fmt&quot; &quot;io&quot; &quot;os&quot;)// cat命令实现func cat(r *bufio.Reader) &#123; for &#123; buf, err := r.ReadBytes(&#x27;
&#x27;) //注意是字符 if err == io.EOF &#123; // 退出之前将已读到的内容输出 fmt.Fprintf(os.Stdout, &quot;%s&quot;, buf) break &#125; fmt.Fprintf(os.Stdout, &quot;%s&quot;, buf) &#125;&#125;func main() &#123; flag.Parse() // 解析命令行参数 if flag.NArg() == 0 &#123; // 如果没有参数默认从标准输入读取内容 cat(bufio.NewReader(os.Stdin)) &#125; // 依次读取每个指定文件的内容并打印到终端 for i := 0; i &lt; flag.NArg(); i++ &#123; f, err := os.Open(flag.Arg(i)) if err != nil &#123; fmt.Fprintf(os.Stdout, &quot;reading from %s failed, err:%v
&quot;, flag.Arg(i), err) continue &#125; cat(bufio.NewReader(f)) &#125;&#125;

1.常见坑1~1001.nil slice &amp; empty slice1.1 nil切片与空切片底层 nil切片：var nilSlice []string nil slice 的长度len和容量cap都是0 nil slice == nil nil slice的pointer 是nil, 空切片：emptySlice0 := make([]int, 0) empty slice的长度是0, 容量是由指向底层数组决定 empty slice != nil empty slice的pointer是底层数组的地址 nil切片和空切片最大的区别在于指向的数组引用地址是不一样的。 nil空切片引用数组指针地址为0（无指向任何实际地址） 空切片的引用数组指针地址是有的，且固定为一个值,所有的空切片指向的数组引用地址都是一样的 1.2 创建nil slice和empty slice1234567891011121314151617181920package mainimport &quot;fmt&quot;func main() &#123; var nilSlice []string // 创建一个 nil 切片 emptySlice0 := make([]int, 0) // 方法1：创建一个空切片（零切片） var emptySlice1 = []string&#123;&#125; // 方法2：创建一个空切片 fmt.Printf(&quot;
nilSlice---&gt; Nil:%v Len:%d Capacity:%d&quot;, nilSlice == nil, len(nilSlice), cap(nilSlice)) fmt.Printf(&quot;
emptySlice0---&gt; nil:%v Len:%d Capacity:%d&quot;, emptySlice0 == nil, len(emptySlice0), cap(emptySlice0)) fmt.Printf(&quot;
emptySlice1---&gt; nil:%v Len:%d Capacity:%d&quot;, emptySlice1 == nil, len(emptySlice1), cap(emptySlice1)) // nil切片和空切片都可以正常 append数据 nilSlice = append(nilSlice, &quot;sss&quot;)&#125;/*Nil:true Len:0 Capacity:0nil:false Len:0 Capacity:0nil:false Len:0 Capacity:0[sss] */ 02.类型强转产生内存拷贝1.1 字符串转数组发送内存拷贝 字符串转成byte数组，会发生内存拷贝吗？ 字符串转成切片，会产生拷贝。 严格来说，只要是发生类型强转都会发生内存拷贝。 那么问题来了，频繁的内存拷贝操作听起来对性能不大友好。 有没有什么办法可以在字符串转成切片的时候不用发生拷贝呢？ 1.2 字符串转数组不内存拷贝方法 那么如果想要在底层转换二者，只需要把 StringHeader 的地址强转成 SliceHeader 就行。那么go有个很强的包叫 unsafe 。 1unsafe.Pointer(&amp;a) 方法可以得到变量 1a 的地址。 2.(*reflect.StringHeader)(unsafe.Pointer(&amp;a)) 可以把字符串a转成底层结构的形式。 3.(*[]byte)(unsafe.Pointer(&amp;ssh)) 可以把ssh底层结构体转成byte的切片的指针。 4.再通过 *转为指针指向的实际内容。 1234567891011121314package mainimport ( &quot;fmt&quot; &quot;reflect&quot; &quot;unsafe&quot;)func main() &#123; a :=&quot;aaa&quot; ssh := *(*reflect.StringHeader)(unsafe.Pointer(&amp;a)) b := *(*[]byte)(unsafe.Pointer(&amp;ssh)) fmt.Printf(&quot;%v---%T&quot;,b,b) // [97 97 97]---[]uint8&#125; 1.3 解释 StringHeader 是字符串在go的底层结构。 1234type StringHeader struct &#123; Data uintptr Len int&#125; SliceHeader 是切片在go的底层结构。 12345type SliceHeader struct &#123; Data uintptr Len int Cap int&#125; 那么如果想要在底层转换二者，只需要把 StringHeader 的地址强转成 SliceHeader 就行。 那么go有个很强的包叫 unsafe 。 1unsafe.Pointer(&amp;a) 方法可以得到变量 1a 的地址。 2.(*reflect.StringHeader)(unsafe.Pointer(&amp;a)) 可以把字符串a转成底层结构的形式。 3.(*[]byte)(unsafe.Pointer(&amp;ssh)) 可以把ssh底层结构体转成byte的切片的指针。 4.再通过 *转为指针指向的实际内容。 03.拷贝大切片一定代价大吗1拷贝大切片一定比小切片代价大吗？ SliceHeader 12345 是 切片 12345678910111213 在go的底层结构。 - 第一个字是指向切片`底层数组的指针`，这是切片的存储空间 - 第二个字段是`切片的长度` - 第三个字段是`容量````gotype SliceHeader struct &#123; Data uintptr Len int Cap int&#125; 大切片跟小切片的区别无非就是 Len 和 Cap的值比小切片的这两个值大一些，如果发生拷贝，本质上就是拷贝上面的三个字段。 所以 拷贝大切片跟小切片的代价应该是一样的。 04.map不初始化使用会怎么样 空map和nil map结果是一样的，都为map[]。 所以，这个时候别断定map是空还是nil，而应该通过map &#x3D;&#x3D; nil来判断。 123456789101112package mainfunc main() &#123; var m1 map[string]string // 创建一个 nil map println(&quot;m1为nil: &quot;, m1==nil) // 报错 =&gt; panic: assignment to entry in nil map //m1[&quot;name&quot;] = &quot;tom&quot; var m2 = make(map[string]string) // 创建一个空map m2[&quot;name&quot;] = &quot;jack&quot; // 空map可以正常 println(&quot;m2为nil: &quot;, m2==nil)&#125; 05.map遍历删除安全吗 map 并不是一个线程安全的数据结构。 同时读写一个 map 是未定义的行为，如果被检测到，会直接 panic。 上面说的是发生在多个协程同时读写同一个 map 的情况下。 如果在同一个协程内边遍历边删除，并不会检测到同时读写，理论上是可以这样做的。 sync.Map可以解决多线程读写map问题 一般而言，这可以通过读写锁来解决：sync.RWMutex。 读之前调用 RLock() 函数，读完之后调用 RUnlock() 函数解锁； 写之前调用 Lock() 函数，写完之后，调用 Unlock() 解锁。 另外，sync.Map 是线程安全的 map，也可以使用。 06.for循环append坑6.1 坑1：添加元素变覆盖 不会死循环，for range其实是golang的语法糖，在循环开始前会获取切片的长度 len(切片)，然后再执行len(切片)次数的循环。 12345678910111213141516package mainimport &quot;fmt&quot;func main() &#123; s := []int&#123;1,2,3,4,5&#125; for _, v:=range s &#123; s =append(s, v) fmt.Printf(&quot;len(s)=%v
&quot;,len(s)) &#125;&#125;/*len(s)=6len(s)=7len(s)=8len(s)=9len(s)=10 */ 6.2 坑2：值全部一样 每次循转中num的值是正常的，但是由append构造的res中，全是nums的最后一个值。 最终总结出原因是在for range语句中，创建了变量num且只被创建了一次。 即num有自己的空间内存且地址在for循环过程中不变 循环过程中每次将nums中对应的值和num进行值传递。 1234567891011121314151617181920package mainimport &quot;fmt&quot;func main() &#123; var nums = []int&#123;1, 2, 3, 4, 5&#125; var res []*int for _, num := range nums &#123; res = append(res, &amp;num) //fmt.Println(&quot;num:&quot;, num) &#125; for _, r := range res &#123; fmt.Println(&quot;res:&quot;, *r) &#125;&#125;/*res: 5res: 5res: 5res: 5res: 5 */ 6.3 解决方法 方法1 123456789101112131415161718 - 不使用for range的形式，直接用索引来对nums取值```gopackage mainimport &quot;fmt&quot;func main() &#123; var nums = []int&#123;1, 2, 3, 4, 5&#125; var res []*int for i := 0; i &lt; len(nums); i++ &#123; res = append(res, &amp;nums[i]) &#125; fmt.Println(&quot;res:&quot;, res) for _, r := range res &#123; fmt.Println(&quot;res:&quot;, *r) &#125;&#125; 方法2 12345678910111213141516171819202122232425262728 - 在for循环中每次再定义一个新的变量num_temp，将num的值传给num_temp，之后append该变量即可。```textpackage mainimport &quot;fmt&quot;func main() &#123; var nums = []int&#123;1, 2, 3, 4, 5&#125; var res []*int for _, num := range nums &#123; numTemp := num // 创建一个新的临时变量 res = append(res, &amp;numTemp) &#125; for _, r := range res &#123; fmt.Println(&quot;res:&quot;, *r) &#125;&#125;/*res: 1res: 2res: 3res: 4res: 5 */
